// ── Vendor Warning Framework ──────────────────────────────────────────────────
//
// Two-layer warning system:
//   Computed  — auto-detected from vendor data on each evaluation (no DB)
//   Persisted — stored in vendor_warnings table (admin-issued or auto-triggered)
//
// Warning types:
//   low_response_rate        — response_rate < 60%
//   inactivity               — no activity in 45+ days
//   excessive_cancellations  — cancellation_rate > 20%
//   dispute_frequency        — multiple unresolved disputes
//   moderation_flags         — suspicious_flag set by admin
//   poor_reviews             — avg rating < 3.5 with 5+ reviews
//   custom                   — admin-issued free-text warning
//
// Severity rankings:
//   low      — informational, no ranking impact
//   medium   — 15% ranking multiplier reduction
//   high     — 30% ranking multiplier reduction
//   critical — 50%+ reduction, removed from featured

export type WarningType =
  | "low_response_rate"
  | "inactivity"
  | "excessive_cancellations"
  | "dispute_frequency"
  | "moderation_flags"
  | "poor_reviews"
  | "custom";

export type WarningSeverity = "low" | "medium" | "high" | "critical";

export interface ComputedWarning {
  type: WarningType;
  severity: WarningSeverity;
  title: string;
  message: string;
  vendorFacingMessage: string;
  rankingPenalty: number; // 0.0–1.0 fraction to remove from ranking multiplier
}

export interface StoredWarning {
  id: string;
  type: WarningType;
  severity: WarningSeverity;
  title: string;
  message: string;
  adminNotes?: string | null;
  autoGenerated: boolean;
  resolved: boolean;
  resolvedAt?: string | null;
  createdAt: string;
}

interface WarningInput {
  status: string;
  rating: number | null;
  review_count: number | null;
  response_rate: number | null;
  cancellation_rate: number | null;
  completed_jobs_count: number | null;
  suspicious_flag: boolean;
  last_active_at?: string | null;
  created_at?: string;
  dispute_count?: number | null;
}

export function detectComputedWarnings(vendor: WarningInput): ComputedWarning[] {
  if (vendor.status !== "approved") return [];

  const warnings: ComputedWarning[] = [];
  const responseRate = vendor.response_rate ?? 0;
  const cancelRate   = vendor.cancellation_rate ?? 0;
  const rating       = vendor.rating ?? 0;
  const reviews      = vendor.review_count ?? 0;
  const daysSinceActive = vendor.last_active_at
    ? (Date.now() - new Date(vendor.last_active_at).getTime()) / (1000 * 60 * 60 * 24)
    : null;

  if (vendor.suspicious_flag) {
    warnings.push({
      type: "moderation_flags",
      severity: "critical",
      title: "Account Under Review",
      message: "This vendor has been flagged for moderation review.",
      vendorFacingMessage: "Your account is currently under review. Contact support if you have questions.",
      rankingPenalty: 0.8,
    });
  }

  if (cancelRate > 30) {
    warnings.push({
      type: "excessive_cancellations",
      severity: "critical",
      title: "Critical Cancellation Rate",
      message: `Cancellation rate is ${cancelRate.toFixed(0)}% — far above the 20% threshold.`,
      vendorFacingMessage: "Your cancellation rate is significantly above marketplace standards and is reducing your visibility.",
      rankingPenalty: 0.5,
    });
  } else if (cancelRate > 20) {
    warnings.push({
      type: "excessive_cancellations",
      severity: "high",
      title: "High Cancellation Rate",
      message: `Cancellation rate is ${cancelRate.toFixed(0)}% — above the 20% threshold.`,
      vendorFacingMessage: "Your cancellation rate is above marketplace standards. Reducing cancellations will improve your ranking.",
      rankingPenalty: 0.3,
    });
  }

  if (responseRate > 0 && responseRate < 40) {
    warnings.push({
      type: "low_response_rate",
      severity: "high",
      title: "Very Low Response Rate",
      message: `Response rate is ${responseRate.toFixed(0)}% — below the 40% minimum.`,
      vendorFacingMessage: "Your response rate dropped below marketplace standards. Responding within 24 hours will restore your visibility.",
      rankingPenalty: 0.3,
    });
  } else if (responseRate > 0 && responseRate < 60) {
    warnings.push({
      type: "low_response_rate",
      severity: "medium",
      title: "Low Response Rate",
      message: `Response rate is ${responseRate.toFixed(0)}% — below the recommended 60%.`,
      vendorFacingMessage: "Your response rate is below the recommended level. Improving it will boost your search ranking.",
      rankingPenalty: 0.15,
    });
  }

  if (reviews >= 5 && rating < 3.0) {
    warnings.push({
      type: "poor_reviews",
      severity: "critical",
      title: "Very Low Review Rating",
      message: `Average rating is ${rating.toFixed(1)} from ${reviews} reviews — below the 3.0 threshold.`,
      vendorFacingMessage: "Your review rating is significantly below marketplace standards and is affecting your visibility.",
      rankingPenalty: 0.5,
    });
  } else if (reviews >= 5 && rating < 3.5) {
    warnings.push({
      type: "poor_reviews",
      severity: "high",
      title: "Below-Average Rating",
      message: `Average rating is ${rating.toFixed(1)} from ${reviews} reviews.`,
      vendorFacingMessage: "Your rating is below the marketplace average. Improving service quality will help restore your ranking.",
      rankingPenalty: 0.25,
    });
  }

  const disputes = vendor.dispute_count ?? 0;
  if (disputes >= 3) {
    warnings.push({
      type: "dispute_frequency",
      severity: "high",
      title: "Multiple Disputes Recorded",
      message: `${disputes} disputes recorded — above acceptable threshold.`,
      vendorFacingMessage: "Multiple disputes have been recorded against your account. Resolving outstanding issues will help restore your standing.",
      rankingPenalty: 0.35,
    });
  } else if (disputes >= 1) {
    warnings.push({
      type: "dispute_frequency",
      severity: "medium",
      title: "Dispute on Record",
      message: `${disputes} dispute recorded on account.`,
      vendorFacingMessage: "A dispute has been recorded on your account. Resolving it promptly will protect your standing.",
      rankingPenalty: 0.1,
    });
  }

  if (daysSinceActive !== null && daysSinceActive > 60) {
    warnings.push({
      type: "inactivity",
      severity: "high",
      title: "Extended Inactivity",
      message: `No activity recorded for ${Math.floor(daysSinceActive)} days.`,
      vendorFacingMessage: "Your profile has been inactive for an extended period. Log in and respond to messages to maintain visibility.",
      rankingPenalty: 0.4,
    });
  } else if (daysSinceActive !== null && daysSinceActive > 30) {
    warnings.push({
      type: "inactivity",
      severity: "medium",
      title: "Inactivity Notice",
      message: `No activity for ${Math.floor(daysSinceActive)} days.`,
      vendorFacingMessage: "Your profile hasn't been active recently. Regular activity helps maintain your search ranking.",
      rankingPenalty: 0.15,
    });
  }

  return warnings;
}

// ── Warning aggregation helpers ───────────────────────────────────────────────

export function combinedRankingMultiplier(warnings: ComputedWarning[]): number {
  // Stack multiplicatively to avoid over-penalizing vendors with multiple minor issues
  return warnings.reduce((m, w) => m * (1 - w.rankingPenalty), 1.0);
}

export function highestSeverity(
  warnings: Array<ComputedWarning | StoredWarning>
): WarningSeverity | null {
  if (warnings.length === 0) return null;
  const order: WarningSeverity[] = ["critical", "high", "medium", "low"];
  for (const severity of order) {
    if (warnings.some((w) => w.severity === severity)) return severity;
  }
  return null;
}

export function hasCriticalOrHighWarning(
  warnings: Array<ComputedWarning | StoredWarning>
): boolean {
  return warnings.some((w) => w.severity === "critical" || w.severity === "high");
}

